17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Objects;
24	import java.util.function.Function;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
45	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
47	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
48	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final TelephoneNormalizer telephoneNormalizer;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper,
83	                                 TelephoneNormalizer telephoneNormalizer,
84	                                 AddressNormalizer addressNormalizer) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	        this.telephoneNormalizer = telephoneNormalizer;
90	        this.addressNormalizer = addressNormalizer;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
122	        rejectBlankOwnerFields(ownerFieldsDto);
123	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
124	        if (!sharesHousehold) {
125	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
126	        }
127	        rejectCityAtCapacity(ownerFieldsDto.getCity());
128	        rejectDailyRegistrationLimit(LocalDate.now());
129	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
130	        rejectDuplicateTelephone(normalizedTelephone);
131	        ownerFieldsDto.setTelephone(normalizedTelephone);
132	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        if (owner.getRegistrationDate() == null) {
136	            owner.setRegistrationDate(LocalDate.now());
137	        }
138	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
139	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
140	        if (sharesHousehold) {
141	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
142	        }
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
162	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
246	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
247	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
248	     * blank (e.g. {@code "   "}). The offending field names are reported through an
249	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
250	     * as a 400 response carrying an {@code errors} array of field names.
251	     *
252	     * @param ownerFieldsDto the submitted owner fields
253	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
254	     */
255	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
256	        List<String> blankFields = new ArrayList<>();
257	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
258	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
259	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
260	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
261	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
262	        if (!blankFields.isEmpty()) {
263	            throw new InvalidOwnerFieldsException(blankFields);
264	        }
265	    }
266	
267	    private void addIfBlank(List<String> blankFields, String field, String value) {
268	        if (value != null && value.isBlank()) {
269	            blankFields.add(field);
270	        }
271	    }
272	
273	    /**
274	     * Normalizes an owner's optional email address. When present it is stored and returned
275	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
276	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
277	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
278	     * method runs.
279	     *
280	     * @param email the raw email value from the request, or {@code null} when omitted
281	     * @return the lower-cased email, or {@code null} when none was supplied
282	     */
283	    private String normalizeEmail(String email) {
284	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
285	    }
286	
287	    /**
288	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
289	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
290	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
291	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
292	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
293	     *
294	     * @param city the city of the owner being created
295	     * @param lastName the last name of the owner being created
296	     * @return the formatted customer code
297	     */
298	    private String nextCustomerCode(String city, String lastName) {
299	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
300	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
301	        long sequence = this.clinicService.findAllOwners().stream()
302	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
303	            .count() + 1L;
304	        return String.format("%s-%s-%04d", city3, last3, sequence);
305	    }
306	
307	    /**
308	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
309	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
310	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
311	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
312	     * new owner and surfaced as the read-only {@code namesakeCount} field.
313	     *
314	     * @param firstName the first name of the owner being created
315	     * @param lastName the last name of the owner being created
316	     * @return the number of existing owners with the same first and last name (case-insensitive)
317	     */
318	    private int namesakeCount(String firstName, String lastName) {
319	        return (int) this.clinicService.findAllOwners().stream()
320	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
321	                && equalsIgnoreCase(owner.getLastName(), lastName))
322	            .count();
323	    }
324	
325	    private boolean equalsIgnoreCase(String a, String b) {
326	        return a == null ? b == null : a.equalsIgnoreCase(b);
327	    }
328	
329	    /**
330	     * The maximum number of owners a single city may contain. Once a city already holds this many
331	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
332	     */
333	    private static final long MAX_OWNERS_PER_CITY = 50L;
334	
335	    /**
336	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
337	     * owners. Existing owners are matched to the requested city case-insensitively (using
338	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
339	     * the per-city counting used for the customer code. A city at capacity is reported through an
340	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
341	     * 409 Conflict response.
342	     *
343	     * @param city the city of the owner being created
344	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
345	     */
346	    private void rejectCityAtCapacity(String city) {
347	        long owners = this.clinicService.findAllOwners().stream()
348	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
349	            .count();
350	        if (owners >= MAX_OWNERS_PER_CITY) {
351	            throw new OwnerCityAtCapacityException(city);
352	        }
353	    }
354	
355	    /**
356	     * The maximum number of owners that may be registered on a single day. Once this many owners
357	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
358	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
359	     */
360	    private static final long MAX_OWNERS_PER_DAY = 100L;
361	
362	    /**
363	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
364	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
365	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
366	     * renders as a 429 Too Many Requests response.
367	     *
368	     * @param date the registration date of the owner being created (today)
369	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
370	     */
371	    private void rejectDailyRegistrationLimit(LocalDate date) {
372	        long owners = this.clinicService.findAllOwners().stream()
373	            .filter(owner -> date.equals(owner.getRegistrationDate()))
374	            .count();
375	        if (owners >= MAX_OWNERS_PER_DAY) {
376	            throw new DailyOwnerRegistrationLimitException(date);
377	        }
378	    }
379	
380	    /**
381	     * Rejects a create request whose normalized telephone is already used by any existing owner.
382	     * Existing owners' telephones are reduced to the same canonical form (via
383	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
384	     * only in formatting still collide. A collision is reported through a
385	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
386	     * as a 409 Conflict response.
387	     *
388	     * @param normalizedTelephone the canonical telephone of the owner being created
389	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
390	     */
391	    private void rejectDuplicateTelephone(String normalizedTelephone) {
392	        boolean duplicate = existingOwnerMatches(
393	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
394	            normalizedTelephone);
395	        if (duplicate) {
396	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
397	        }
398	    }
399	
400	    /**
401	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
402	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
403	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
404	     * and the owner being created to the same canonical key and reject a match.
405	     *
406	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
407	     * @param key the canonical key of the owner being created
408	     * @return {@code true} if some existing owner shares the key
409	     */
410	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
411	        return this.clinicService.findAllOwners().stream()
412	            .map(keyExtractor)
413	            .filter(Objects::nonNull)
414	            .anyMatch(key::equals);
415	    }
416	
417	    /**
418	     * Rejects a create request that shares a household with an existing owner: another owner already
419	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
420	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
421	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
422	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
423	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
424	     * check when the request opts in via {@code sharesHousehold}.
425	     *
426	     * @param lastName the last name of the owner being created
427	     * @param address the address of the owner being created
428	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
429	     */
430	    private void rejectDuplicateHousehold(String lastName, String address) {
431	        String canonicalLastName = canonicalizeHousehold(lastName);
432	        String canonicalAddress = canonicalizeHousehold(address);
433	        if (canonicalLastName == null || canonicalAddress == null) {
434	            return;
435	        }
436	        boolean duplicate = this.clinicService.findAllOwners().stream()
437	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
438	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
439	        if (duplicate) {
440	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
441	        }
442	    }
443	
444	    /**
445	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
446	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
447	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
448	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
449	     *
450	     * @param value the raw field value, or {@code null}
451	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
452	     */
453	    private String canonicalizeHousehold(String value) {
454	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
455	    }
456	
457	    /**
458	     * Derives the stable, shared {@code householdId} for an owner joining a household via
459	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
460	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
461	     * owner with the same last name at the same address - regardless of casing or spacing - is
462	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
463	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
464	     *
465	     * @param lastName the last name of the owner being created
466	     * @param address the address of the owner being created
467	     * @return the shared household identifier
468	     */
469	    private String householdId(String lastName, String address) {
470	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
471	        try {
472	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
473	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
474	            StringBuilder sb = new StringBuilder(digest.length * 2);
475	            for (byte b : digest) {
476	                sb.append(String.format("%02X", b));
477	            }
478	            return sb.substring(0, 16);
479	        } catch (java.security.NoSuchAlgorithmException e) {
480	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
481	        }
482	    }
483	}
